package com.xpertsedge.hrms;
import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@RestController @RequestMapping("/api/webmail/security") public class MailSecurityController {
 @org.springframework.beans.factory.annotation.Autowired private LoginAttemptRepo attempts;
 private final WebmailAuth auth;private final MailMfa mfa;private final BCryptPasswordEncoder encoder;private final WebmailSessionRepo sessions;
 public MailSecurityController(WebmailAuth auth,MailMfa mfa,BCryptPasswordEncoder encoder,WebmailSessionRepo sessions){this.auth=auth;this.mfa=mfa;this.encoder=encoder;this.sessions=sessions;}
 Mailbox password(Map<String,Object>b,HttpServletRequest r){Mailbox box=auth.current(r);String key="mfa:"+box.id;java.time.Instant now=java.time.Instant.now();LoginAttempt attempt=attempts.findById(key).orElseGet(()->{LoginAttempt a=new LoginAttempt();a.email=key;return a;});if(attempt.windowStart==null||!attempt.windowStart.plusSeconds(900).isAfter(now)){attempt.windowStart=now;attempt.failures=0;}if(attempt.failures>=5)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS,"Too many security attempts. Retry after 15 minutes.");attempt.failures++;attempts.save(attempt);String password=WebmailController.text(b,"password",72);if(!encoder.matches(password,box.passwordHash))throw WebmailAuth.unauthorized();return box;}
 @GetMapping public Map<String,Object> status(HttpServletRequest r){return Map.of("enabled",mfa.enabled(auth.current(r).id));}
 @PostMapping("/setup") public synchronized Map<String,Object> setup(@RequestBody Map<String,Object>b,HttpServletRequest r){Mailbox box=password(b,r);String secret=mfa.setup(box.id);attempts.deleteById("mfa:"+box.id);return Map.of("secret",secret,"issuer","XpertsEdge Mail","account",auth.email(box),"expiresIn",300);}
 @PostMapping("/confirm") public synchronized Map<String,Object> confirm(@RequestBody Map<String,Object>b,HttpServletRequest r){Mailbox box=password(b,r);List<String> codes=mfa.confirm(box.id,WebmailController.text(b,"code",40));sessions.deleteByOwnerId(box.id);attempts.deleteById("mfa:"+box.id);return Map.of("recoveryCodes",codes,"message","2FA enabled. Save recovery codes, then sign in again.");}
 @PostMapping("/disable") public synchronized Map<String,Object> disable(@RequestBody Map<String,Object>b,HttpServletRequest r){Mailbox box=password(b,r);mfa.disable(box.id,WebmailController.text(b,"code",40));sessions.deleteByOwnerId(box.id);attempts.deleteById("mfa:"+box.id);return Map.of("message","2FA disabled. Sign in again.");}
}
